":"page","code":"numbering.tasks","allowed":true}],"roleDefinitionHash":"e7ff57ed1ca6d2d99e6e052f1f48829365093a32a1d6bb9f8503490a3e7bcbfc"}],"catalogSha256":"320b259f0f0b4a51f24227cff37313bcb5fa3834d7736df3c43a1e178b878a73"},"roleProfiles":[{"stableRoleId":"role-rd","permissionRoleId":"role-rd","presentationName":"研發人員","presentationOrder":0,"assignmentDisposition":"selectable"},{"stableRoleId":"role-rd-manager","permissionRoleId":"role-rd-manager","presentationName":"研發主管","presentationOrder":1,"assignmentDisposition":"selectable"},{"stableRoleId":"role-qa","permissionRoleId":"role-qa","presentationName":"QA/QC","presentationOrder":2,"assignmentDisposition":"selectable"},{"stableRoleId":"role-manufacturing","permissionRoleId":"role-manufacturing","presentationName":"生產人員","presentationOrder":3,"assignmentDisposition":"selectable"},{"stableRoleId":"role-production-planning","permissionRoleId":"role-production-planning","presentationName":"生管人員","presentationOrder":4,"assignmentDisposition":"selectable"},{"stableRoleId":"role-procurement","permissionRoleId":"role-procurement","presentationName":"採購","presentationOrder":5,"assignmentDisposition":"selectable"},{"stableRoleId":"role-external-specialist","permissionRoleId":"role-external-specialist","presentationName":"外部專員","presentationOrder":6,"assignmentDisposition":"selectable"},{"stableRoleId":"role-pdm-admin","permissionRoleId":"role-pdm-admin","presentationName":"PDM管理員","presentationOrder":7,"assignmentDisposition":"selectable"},{"stableRoleId":"role-system-admin","permissionRoleId":"role-system-admin","presentationName":"系統管理員","presentationOrder":8,"assignmentDisposition":"hidden-protected"},{"stableRoleId":"role-application-system-admin","permissionRoleId":"role-application-system-admin","presentationName":"系統管理員","presentationOrder":9,"assignmentDisposition":"hidden-protected"}]}$dev127_payload$::jsonb;
 existing ai_pdm_core.dev127_static_catalog_commands%ROWTYPE;
 active_version text; active_hash text; previous_format text; previous_profiles jsonb;
 request_hash text; observed_roles jsonb; expected_roles jsonb; role_value jsonb; identity_value jsonb; result jsonb;
BEGIN
 IF current_user<>'jenfu_ai_pdm_migrator' OR p_source_revision IS NULL OR p_source_revision !~ '^[a-f0-9]{40}$'
   OR p_binding_sha256 IS NULL OR p_binding_sha256 !~ '^[a-f0-9]{64}$'
   OR p_request_id IS NULL OR p_request_id::text !~ '^[a-f0-9]{8}-[a-f0-9]{4}-5[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
   OR pg_catalog.shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database')
     IS DISTINCT FROM 'local-first-admin-corrected-genesis:16930fa3-b7cd-4c7c-947d-c3203e59178c'
 THEN RAISE EXCEPTION 'DEV127_LOCAL_STATIC_SOURCE_INVALID' USING ERRCODE='42501'; END IF;
 IF p_expected_version IS DISTINCT FROM 'ai-pdm.role-catalog.2026-10-10.v7'
   OR p_expected_sha256 IS DISTINCT FROM '4d624b16a58299a78bc3bac4b7f39f261ec2ba34ae604f06ed7cdb7a078e01f9'
 THEN RAISE EXCEPTION 'DEV127_LOCAL_STATIC_BASELINE_INVALID' USING ERRCODE='22023'; END IF;
 request_hash:=ai_pdm_core.dev123_json_sha256_v1(jsonb_build_object(
   'operation','STATIC_ADDITIVE_APPLICATION_ADMIN_V8','commandId',p_request_id::text,'sourceRevision',p_source_revision,
   'bindingSha256',p_binding_sha256,'expectedActive',jsonb_build_object('catalogVersion',p_expected_version,'catalogSha256',p_expected_sha256),
   'catalogPayloadSha256',ai_pdm_core.dev123_json_sha256_v1(payload)));
 PERFORM pg_advisory_xact_lock(hashtextextended(p_request_id::text,0));
 SELECT * INTO existing FROM ai_pdm_core.dev127_static_catalog_commands WHERE request_id=p_request_id;
 IF FOUND THEN
   IF existing.request_hash<>request_hash THEN RAISE EXCEPTION 'DEV127_LOCAL_STATIC_REQUEST_REUSE' USING ERRCODE='23505'; END IF;
   RETURN existing.result_json;
 END IF;
 SELECT publication.catalog_version,publication.catalog_sha256,publication.publication_format,publication.role_profiles
   INTO STRICT active_version,active_hash,previous_format,previous_profiles
 FROM ai_pdm_core.active_role_catalog active JOIN ai_pdm_core.role_catalog_publications publication
   ON publication.application_id=active.application_id AND publication.catalog_version=active.catalog_version
 WHERE active.application_id='ai-pdm' AND publication.status='active' FOR UPDATE OF active,publication;
 IF active_version IS DISTINCT FROM p_expected_version OR active_hash IS DISTINCT FROM p_expected_sha256
   OR previous_format IS NOT NULL OR previous_profiles IS NOT NULL
   OR EXISTS(SELECT 1 FROM ai_pdm_core.role_catalog_publications WHERE application_id='ai-pdm' AND publication_format IN ('dynamic-policy-v1','dynamic-policy-v2'))
   OR EXISTS(SELECT 1 FROM ai_pdm_core.role_policy_drafts WHERE status='OPEN')
   OR EXISTS(SELECT 1 FROM ai_pdm_core.role_policy_commands)
 THEN RAISE EXCEPTION 'DEV127_LOCAL_STATIC_ACTIVE_CONFLICT' USING ERRCODE='40001'; END IF;
 SELECT jsonb_agg(jsonb_build_object('stableRoleId',stable_role_id,'roleCode',role_code,'displayName',display_name,
   'assignable',assignable,'risk',risk,'subjectKind',subject_kind,'recommendationAllowed',recommendation_allowed,
   'delegationAllowed',delegation_allowed,'allowedScopeKinds',allowed_scope_kinds,'assignmentTier',assignment_tier,
   'permissions',permissions,'metadata',coalesce(metadata,'null'::jsonb),'roleDefinitionHash',role_definition_hash,'roleStatus',role_status)
   ORDER BY display_order) INTO observed_roles FROM ai_pdm_core.role_catalog_entries WHERE catalog_version=active_version;
 SELECT jsonb_agg(value||jsonb_build_object('metadata',coalesce(value->'metadata','null'::jsonb),'roleStatus','active') ORDER BY n)
   INTO expected_roles FROM jsonb_array_elements(payload->'catalog'->'roles') WITH ORDINALITY r(value,n) WHERE n<=9;
 IF observed_roles IS DISTINCT FROM expected_roles
   OR (SELECT count(*) FROM ai_pdm_core.role_policy_role_identities)<>9
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(expected_roles) role LEFT JOIN ai_pdm_core.role_policy_role_identities claim
     ON claim.stable_role_id=role->>'stableRoleId'
     WHERE claim.identity_json IS DISTINCT FROM role-ARRAY['permissions','roleStatus','roleDefinitionHash']
       OR claim.identity_hash IS DISTINCT FROM ai_pdm_core.dev123_json_sha256_v1(role-ARRAY['permissions','roleStatus','roleDefinitionHash'])
       OR claim.first_catalog_version IS DISTINCT FROM active_version)
 THEN RAISE EXCEPTION 'DEV127_LOCAL_STATIC_ROLE_DRIFT' USING ERRCODE='40001'; END IF;
 UPDATE ai_pdm_core.role_catalog_publications SET status='retired',retired_at=clock_timestamp()
   WHERE catalog_version=active_version AND application_id='ai-pdm' AND status='active';
 INSERT INTO ai_pdm_core.role_catalog_publications(catalog_version,contract_version,application_id,published_at,catalog_sha256,status,
   published_by,publication_format,role_profiles,role_profile_schema_id,role_profile_hash,base_catalog_version,base_catalog_sha256,command_id,publish_reason)
 VALUES(payload->'catalog'->>'catalogVersion','jenfu.platform-entitlement.v1','ai-pdm',clock_timestamp(),payload->'catalog'->>'catalogSha256','active',
   'owner:DEV-127','legacy-static-v1',payload->'roleProfiles','ai-pdm.static-role-profiles.v1',ai_pdm_core.dev123_json_sha256_v1(payload->'roleProfiles'),
   active_version,active_hash,p_request_id,'DEV-127 exact static protected administrator addition; business policy unchanged');
 INSERT INTO ai_pdm_core.role_catalog_entries(catalog_version,display_order,stable_role_id,role_code,display_name,assignable,risk,subject_kind,
   recommendation_allowed,delegation_allowed,allowed_scope_kinds,assignment_tier,permissions,metadata,role_definition_hash,role_status)
 SELECT payload->'catalog'->>'catalogVersion',display_order,stable_role_id,role_code,display_name,
   assignable,risk,subject_kind,recommendation_allowed,delegation_allowed,allowed_scope_kinds,assignment_tier,permissions,metadata,role_definition_hash,role_status
   FROM ai_pdm_core.role_catalog_entries WHERE catalog_version=active_version;
 role_value:=payload->'catalog'->'roles'->9;
 INSERT INTO ai_pdm_core.role_catalog_entries(catalog_version,display_order,stable_role_id,role_code,display_name,assignable,risk,subject_kind,
   recommendation_allowed,delegation_allowed,allowed_scope_kinds,assignment_tier,permissions,metadata,role_definition_hash,role_status)
 VALUES(payload->'catalog'->>'catalogVersion',9,role_value->>'stableRoleId',role_value->>'roleCode',
   role_value->>'displayName',(role_value->>'assignable')::boolean,role_value->>'risk',role_value->>'subjectKind',
   (role_value->>'recommendationAllowed')::boolean,(role_value->>'delegationAllowed')::boolean,role_value->'allowedScopeKinds',
   role_value->>'assignmentTier',role_value->'permissions',role_value->'metadata',role_value->>'roleDefinitionHash','active');
 identity_value:=role_value-ARRAY['permissions','roleStatus','roleDefinitionHash'];
 INSERT INTO ai_pdm_core.role_policy_role_identities(stable_role_id,role_code,display_name,origin,identity_json,identity_hash,first_catalog_version)
 VALUES(role_value->>'stableRoleId',role_value->>'roleCode',role_value->>'displayName','builtin',identity_value,
   ai_pdm_core.dev123_json_sha256_v1(identity_value),payload->'catalog'->>'catalogVersion');
 UPDATE ai_pdm_core.active_role_catalog SET catalog_version=payload->'catalog'->>'catalogVersion',activated_at=clock_timestamp(),
   activated_by='owner:DEV-127',activation_reason='DEV-127 static administrator addition; no business policy transition'
   WHERE application_id='ai-pdm' AND catalog_version=active_version;
 IF NOT FOUND THEN RAISE EXCEPTION 'DEV127_LOCAL_STATIC_ACTIVE_CONFLICT' USING ERRCODE='40001'; END IF;
 result:=jsonb_build_object('status','ACTIVE','commandId',p_request_id::text,
   'active',jsonb_build_object('catalogVersion',payload->'catalog'->>'catalogVersion','catalogSha256',payload->'catalog'->>'catalogSha256'),
   'previousActive',jsonb_build_object('catalogVersion',active_version,'catalogSha256',active_hash),
   'preservedLegacyRoles',9,'businessPolicyPublished',false,'assignmentWrites',0);
 INSERT INTO ai_pdm_core.dev127_static_catalog_commands(request_id,request_hash,source_revision,binding_sha256,result_json)
 VALUES(p_request_id,request_hash,p_source_revision,p_binding_sha256,result);
 RETURN result;
END $publish$;
REVOKE ALL ON FUNCTION ai_pdm_core.dev127_publish_static_v8(uuid,text,text,text,text)
 FROM PUBLIC,jenfu_ai_pdm_runtime,jenfu_platform_runtime,jenfu_orgmaster_runtime,jenfu_r1_verifier;
-- Do not inherit any unrelated default ACL onto these two new owner objects.
DO $acl$ DECLARE owner_oid oid; BEGIN
 SELECT oid INTO STRICT owner_oid FROM pg_roles WHERE rolname='jenfu_ai_pdm_migrator';
 IF EXISTS(SELECT 1 FROM pg_proc p LEFT JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl ON true
     WHERE p.oid='ai_pdm_core.dev127_publish_static_v8(uuid,text,text,text,text)'::regprocedure
       AND (p.proowner<>owner_oid OR acl.grantee<>owner_oid))
   OR EXISTS(SELECT 1 FROM pg_class c LEFT JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) acl ON true
     WHERE c.oid='ai_pdm_core.dev127_static_catalog_commands'::regclass AND (c.relowner<>owner_oid OR acl.grantee<>owner_oid))
 THEN RAISE EXCEPTION 'DEV127_LOCAL_STATIC_OWNER_ACL_INVALID' USING ERRCODE='42501'; END IF;
END $acl$;
